--
-- Tabelstructuur voor tabel `supplier`
--

DROP TABLE IF EXISTS `supplier`;
CREATE TABLE IF NOT EXISTS `supplier` (
  `ID` int NOT NULL AUTO_INCREMENT,
  `company` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `adress` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `streetnr` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `zipcode` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `city` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `state` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `countryid` int DEFAULT NULL,
  `telephone` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `website` varchar(1000) COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

